                reservationService.createReservation(
                        "999", "João Silva", "joao@email.com", "12345678900",
                        LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12),
                        2, RatePlan.STANDARD));
    }

    @Test
