        reservationService.confirmReservation(r1.getId());

        String csv = reportService.generateRatePlansReport(YearMonth.of(2027, 7));

        assertTrue(csv.contains("STANDARD,1,"));
        assertTrue(csv.contains("NON_REFUNDABLE,0,0.00"));
    }
}

