1	package com.pousadamarealta;
2	
3	import com.fasterxml.jackson.databind.ObjectMapper;
4	import com.fasterxml.jackson.databind.SerializationFeature;
5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
6	import com.pousadamarealta.api.ApiHandler;
7	import com.pousadamarealta.repository.MessageRepository;
8	import com.pousadamarealta.repository.ReservationRepository;
9	import com.pousadamarealta.repository.RoomRepository;
10	import com.pousadamarealta.service.PricingService;
11	import com.pousadamarealta.service.ReportService;
12	import com.pousadamarealta.service.ReservationService;
13	import io.javalin.Javalin;
14	import io.javalin.json.JavalinJackson;
15	
16	public class App {
17	    public static void main(String[] args) {
18	        int port = getPort();
19	
20	        RoomRepository roomRepository = new RoomRepository();
21	        ReservationRepository reservationRepository = new ReservationRepository();
22	        MessageRepository messageRepository = new MessageRepository();
23	        PricingService pricingService = new PricingService();
24	
25	        ReservationService reservationService = new ReservationService(
26	                reservationRepository, roomRepository, messageRepository, pricingService);
27	
28	        ReportService reportService = new ReportService(
29	                reservationRepository, roomRepository, pricingService);
30	
31	        ApiHandler handler = new ApiHandler(
32	                roomRepository, reservationService, reservationRepository, messageRepository, reportService);
33	
34	        ObjectMapper objectMapper = new ObjectMapper();
35	        objectMapper.registerModule(new JavaTimeModule());
36	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
37	
38	        Javalin app = Javalin.create(config -> {
39	            config.jsonMapper(new JavalinJackson(objectMapper));
40	        });
41	
42	        app.get("/rooms", handler::getRooms);
43	        app.post("/reservations", handler::createReservation);
44	        app.get("/reservations/{id}", handler::getReservation);
45	        app.post("/reservations/{id}/confirmation", handler::confirmReservation);
46	        app.post("/reservations/{id}/cancellation", handler::cancelReservation);
47	        app.post("/reservations/{id}/check-in", handler::checkIn);
48	        app.post("/reservations/{id}/check-out", handler::checkOut);
49	        app.get("/reservations/{id}/document", handler::getDocument);
50	        app.get("/messages", handler::getMessages);
51	        app.get("/reports/occupancy", handler::getOccupancyReport);
52	        app.get("/reports/revenue", handler::getRevenueReport);
53	        app.get("/reports/tourism-tax", handler::getTourismTaxReport);
54	        app.get("/reports/rate-plans", handler::getRatePlansReport);
55	
56	        app.exception(Exception.class, handler::handleException);
57	
58	        app.start(port);
59	
60	        System.out.println("Pousada Maré Alta - Sistema de Reservas");
61	        System.out.println("Servidor iniciado na porta " + port);
62	    }
63	
64	    private static int getPort() {
65	        String portEnv = System.getenv("PORT");
66	        if (portEnv != null && !portEnv.isEmpty()) {
67	            try {
